Text.text:
{
            parts: [
              { path: 'Nature', targetType: 'any' },
              { path: 'InstallmentNumber', targetType: 'any' },
              { path: 'WithholdingTaxType', targetType: 'any' }
            ],
            formatter: 'draft.formatGeneratedTitle'
          }

{
            path: 'DueDate',
            type: 'sap.ui.model.odata.type.DateTimeOffset',
            constraints: { precision: 7 },
            formatOptions: { pattern: 'dd/MM/yyyy' }
          }

{
            path: 'NetAmount',
            type: 'sap.ui.model.odata.type.Decimal',
            constraints: { precision: 18, scale: 2 },
            formatOptions: { decimalSeparator: ',', groupingEnabled: true, groupingSeparator: '.' }
          }

{
            path: 'OpenAmount',
            type: 'sap.ui.model.odata.type.Decimal',
            constraints: { precision: 18, scale: 2 },
            formatOptions: { decimalSeparator: ',', groupingEnabled: true, groupingSeparator: '.' }
          }
